mapper.select:
SELECT 1
FROM pubcar_driver
WHERE community_id = #{communityId} AND status_cd = '0' AND (tel = #{tel}

    OR job_num = #{jobNum}


    OR staff_car_num = #{staffCarNum}


    OR id_num = #{idNum}
)

    AND driver_id <> #{driverId}

LIMIT 1;

SELECT t.driver_id driverId, t.name, t.gender, o.org_name department, d.name position, t.tel, t.job_num jobNum, (CASE WHEN m.mileage IS NULL THEN 0 ELSE m.mileage END) mileage, (CASE WHEN m.duration IS NULL THEN 0 ELSE m.duration END) duration, (CASE WHEN m.tripNum IS NULL THEN 0 ELSE m.tripNum END) tripNum FROM pubcar_driver t LEFT JOIN u_org o on o.org_id = t.department_id LEFT JOIN t_dict d ON d.status_cd = t.position_id AND d.table_name = 'u_org_staff_rel' AND d.table_columns = 'rel_cd' LEFT JOIN ( SELECT driver_id, SUM(pass_mileage) mileage, SUM(duration) duration, COUNT(mileage_id) tripNum FROM pubcar_trip_mileage
start_time >= #{startTime}
AND end_time <= #{endTime}
GROUP BY driver_id ) m ON m.driver_id = t.driver_id WHERE t.status_cd = '0'
AND t.name like concat('%',#{name},'%')
and t.job_num like concat('%',#{jobNum},'%')
and t.tel like concat('%',#{tel},'%')
and d.name like concat('%',#{position},'%')
and o.org_name like concat('%',#{department},'%')
and t.community_id= #{communityId}
order by t.create_time ASC
limit #{page}, #{row}

select u.b_id bId, u.driver_id driverId, u.name, u.gender, u.department_id departmentId, u.position_id positionId, u.tel, u.job_num jobNum, u.staff_car_num staffCarNum,
       u.id_num idNum, u.education, u.remark, u.group_id groupId, u.portrait, u.community_id communityId
from business_pubcar_driver u


        u.b_id = #{bId}


        and u.operate = #{operate}

