insert into pubcar_driver(driver_id, name, password, gender, department_id, position_id, tel, job_num, staff_car_num, id_num, education, remark, group_id, portrait, b_id, status_cd, community_id) select t.driver_id, t.name, t.password, t.gender, t.department_id, t.position_id, t.tel, t.job_num, t.staff_car_num, t.id_num, t.education, t.remark, t.group_id, t.portrait, t.b_id, '0', t.community_id from business_pubcar_driver t
t.b_id= #{bId}
and t.operate= #{operate}

