select t.driver_id driverId,t.name,t.gender,t.department_id departmentId,t.position_id positionId,t.tel,t.job_num jobNum,
t.staff_car_num staffCarNum,t.id_num idNum,t.education,t.remark,t.group_id groupId,t.portrait,t.community_id communityId
from pubcar_driver t


        t.driver_id= #{driverId}


        and t.job_num like concat('%',#{jobNum},'%')


        and t.gender= #{gender}


        and t.status_cd= #{statusCd}


        and t.password= #{password}


        and t.name like concat('%',#{name},'%')


        and t.tel like concat('%',#{tel},'%')


        and t.department_id= #{departmentId}


        and t.b_id= #{bId}


        and t.community_id= #{communityId}

    order by t.create_time DESC

        limit #{page}, #{row}

